[
  {
    "text": "VLM-IE3D introduces Implicit Geometry Tokens (IGTs) that capture high-level geometric priors from input videos.",
    "topic": "Implicit Geometry Tokens"
  },
  {
    "text": "VLM-IE3D introduces Explicit Geometry Tokens (EGTs) that encode detailed geometric structures from reconstructed 3D attributes.",
    "topic": "Explicit Geometry Tokens"
  },
  {
    "text": "VLM-IE3D uses a 3D-aware adapter to fuse implicit and explicit geometric representations with 2D visual cues.",
    "topic": "3D-aware Adapter"
  },
  {
    "text": "VLM-IE3D achieves superior performance across 3D video detection, 3D visual grounding, 3D dense captioning, and spatial reasoning tasks.",
    "topic": "Performance on 3D Tasks"
  },
  {
    "text": "VLM-IE3D is an RGB-only design that injects strong 3D inductive biases without requiring additional 3D inputs.",
    "topic": "RGB-Only Design"
  }
]
